#!/usr/bin/env python3
"""gen_palette.py out.h
Generate the 256 AGA colour-register values of the Amiga port: index = NES colour (bits 0..5) | red emphasis (bit 6) | green emphasis (bit 7).
Blue emphasis is not displayed (8 bitplanes only).  The 64 base colours are the default palette of the Mesen libretro core
(libretro/Mesen Libretro/libretro.cpp `defaultPalette`, loaded with SetUserRgbPalette) and the emphasis is applied exactly like Mesen's
EmulationSettings::GenerateFullColorPalette (the other two guns are multiplied by 0.84 per emphasis bit, columns $xE/$xF unaffected, truncated to 8 bits).
Output: C array `const uint32_t nes_rgb[256]` (0x00RRGGBB)."""
import sys
BASE = [0x666666,0x002A88,0x1412A7,0x3B00A4,0x5C007E,0x6E0040,0x6C0600,0x561D00,0x333500,0x0B4800,0x005200,0x004F08,0x00404D,0x000000,0x000000,0x000000,
        0xADADAD,0x155FD9,0x4240FF,0x7527FE,0xA01ACC,0xB71E7B,0xB53120,0x994E00,0x6B6D00,0x388700,0x0C9300,0x008F32,0x007C8D,0x000000,0x000000,0x000000,
        0xFFFEFF,0x64B0FF,0x9290FF,0xC676FF,0xF36AFF,0xFE6ECC,0xFE8170,0xEA9E22,0xBCBE00,0x88D800,0x5CE430,0x45E082,0x48CDDE,0x4F4F4F,0x000000,0x000000,
        0xFFFEFF,0xC0DFFF,0xD3D2FF,0xE8C8FF,0xFBC2FF,0xFEC4EA,0xFECCC5,0xF7D8A5,0xE4E594,0xCFEF96,0xBDF4AB,0xB3F3CC,0xB5EBF2,0xB8B8B8,0x000000,0x000000]
def full(j):
    out = []
    for i in range(64):
        r = float((BASE[i] >> 16) & 255); g = float((BASE[i] >> 8) & 255); b = float(BASE[i] & 255)
        if j and (i & 0x0F) <= 0x0D:
            if j & 1: g *= 0.84; b *= 0.84
            if j & 2: r *= 0.84; b *= 0.84
            if j & 4: r *= 0.84; g *= 0.84
        out.append((int(min(r, 255)) << 16) | (int(min(g, 255)) << 8) | int(min(b, 255)))
    return out
def table():
    t = []
    for j in range(4): t += full(j)
    return t
if __name__ == '__main__':
    t = table()
    with open(sys.argv[1], 'w') as f:
        f.write('/* generated by tools/gen_palette.py - do not edit.  index = NES colour | red emphasis << 6 | green emphasis << 7 */\n')
        f.write('const uint32_t nes_rgb[256] = {\n')
        for i in range(0, 256, 8): f.write('    ' + ', '.join('0x%06X' % v for v in t[i:i+8]) + ',\n')
        f.write('};\n')
